import re
from pydantic import BaseModel, Field, field_validator

ALLOWED_ACTIONS = {"refund", "resend_invoice"}
CARD = re.compile(r"\b(?:\d[ -]?){13,19}\b")

def luhn_ok(number: str) -> bool:
    digits = [int(d) for d in re.sub(r"\D", "", number)][::-1]
    total = sum(d if i % 2 == 0 else (d * 2 - 9 if d > 4 else d * 2)
                for i, d in enumerate(digits))
    return total % 10 == 0

def mask_cards(text: str) -> str:
    return CARD.sub(lambda m: "[CARD]" if luhn_ok(m.group()) else m.group(), text)

class RefundCall(BaseModel):
    action: str
    amount_inr: float = Field(gt=0, le=50_000)

    @field_validator("action")
    @classmethod
    def allowed(cls, v: str) -> str:
        if v not in ALLOWED_ACTIONS:
            raise ValueError(f"action '{v}' is not allowed")
        return v

print(mask_cards("card 4111 1111 1111 1111"))   # card [CARD]
RefundCall(action="refund", amount_inr=75_000)  # raises ValidationError
